				if (${await_block_type} !== ${create_pending_block}) {
					${replace_await_block}(${token}, ${create_pending_block}, null, ${params});
					return true;
				}
			} else {
				${resolved} = ${promise};
				if (${await_block_type} !== ${create_then_block}) {
					${replace_await_block}(${token}, ${create_then_block}, ${resolved}, ${params});
					return true;
				}
			}
