	if (node.metadata.dependencies) {
		conditions.push(
			`(${node.metadata.dependencies.map(dep => `'${dep}' in changed`).join(' || ')})`
		);
	}

	conditions.push(
		`${promise} !== (${promise} = ${snippet})`,
		`${handle_promise}(${promise}, ${params})`
