const dom = new JSDOM('<!doctype html><html><body></body></html>');
global.window = dom.window;
global.document = dom.window.document;
const source = '<div>{{#await promise}}pending{{then value}}{{value}}{{catch error}}error{{/await}}</div>';
const code = svelte.compile(source).code;
assert(!code.includes('null.parentNode'));
const mod = { exports: {} };
new Function('module', 'exports', 'require', code)(mod, mod.exports, require);
let resolve;
const promise = new Promise(fulfil => { resolve = fulfil; });
const target = document.createElement('main');
const App = mod.exports;
const component = new App({ target, data: { promise } });
assert.strictEqual(target.innerHTML, '<div>pending</div>');
resolve('done');
promise.then(() => {
  assert.strictEqual(target.innerHTML, '<div>done</div>');
  component.destroy();
  console.log('await block without a comment anchor resolves and replaces content');
}).catch(error => { console.error(error); process.exitCode = 1; });
